<?php
declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
$method=$_SERVER['REQUEST_METHOD'];$path='/'.trim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/');$path=preg_replace('#^/api(?=/|$)#','',$path)?:'/';
try{
 if($method==='GET'&&$path==='/health')respond(['status'=>'ok']);
 if($method==='GET'&&$path==='/csrf'){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));respond(['token'=>$_SESSION['csrf']]);}
 if($method==='GET'&&$path==='/me'){if(empty($_SESSION['user_id']))respond(['user'=>null,'csrf'=>$_SESSION['csrf']??null]);$s=$pdo->prepare('SELECT id,name,email FROM users WHERE id=?');$s->execute([$_SESSION['user_id']]);respond(['user'=>$s->fetch(),'csrf'=>$_SESSION['csrf']??null]);}
 if($method==='POST'&&$path==='/auth/register'){$b=body();$name=trim((string)($b['name']??''));$email=strtolower(trim((string)($b['email']??'')));$pw=(string)($b['password']??'');if(strlen($name)<2||strlen($name)>80||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)respond(['error'=>'Enter a name, valid email and password with at least 8 characters.'],422);try{$s=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);}catch(PDOException $e){if($e->getCode()==='23000')respond(['error'=>'An account with this email already exists.'],409);throw $e;}session_regenerate_id(true);$_SESSION['user_id']=(int)$pdo->lastInsertId();$_SESSION['csrf']=bin2hex(random_bytes(32));respond(['user'=>['id'=>$_SESSION['user_id'],'name'=>$name,'email'=>$email],'csrf'=>$_SESSION['csrf']],201);}
 if($method==='POST'&&$path==='/auth/login'){$b=body();$s=$pdo->prepare('SELECT id,name,email,password_hash FROM users WHERE email=?');$s->execute([strtolower(trim((string)($b['email']??'')))]);$u=$s->fetch();if(!$u||!password_verify((string)($b['password']??''),$u['password_hash']))respond(['error'=>'Email or password is incorrect.'],401);session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));unset($u['password_hash']);respond(['user'=>$u,'csrf'=>$_SESSION['csrf']]);}
 if($method==='POST'&&$path==='/auth/logout'){userId();csrf();$_SESSION=[];session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(32));respond(['ok'=>true,'csrf'=>$_SESSION['csrf']]);}
 if($method==='GET'&&$path==='/home'){$hero=$pdo->query("SELECT id,title,subtitle,image_url,tag FROM home_blocks WHERE block_key='hero' AND active=1 ORDER BY sort_order LIMIT 1")->fetch();$best=$pdo->query("SELECT p.*,MIN(o.price) lowest_price,COUNT(o.id) offer_count FROM home_blocks h JOIN products p ON p.id=h.product_id JOIN offers o ON o.product_id=p.id AND o.stock>0 WHERE h.block_key='bestsellers' AND h.active=1 GROUP BY p.id ORDER BY h.sort_order")->fetchAll();$deals=$pdo->query("SELECT p.*,MIN(o.price) lowest_price,COUNT(o.id) offer_count FROM home_blocks h JOIN products p ON p.id=h.product_id JOIN offers o ON o.product_id=p.id AND o.stock>0 WHERE h.block_key='deals' AND h.active=1 GROUP BY p.id ORDER BY h.sort_order")->fetchAll();respond(['hero'=>$hero,'bestsellers'=>$best,'deals'=>$deals]);}
 if($method==='GET'&&$path==='/products'){$q=trim((string)($_GET['q']??''));$platform=(string)($_GET['platform']??'');$region=(string)($_GET['region']??'');$sort=(string)($_GET['sort']??'popular');$min=max(0,(float)($_GET['min']??0));$max=(float)($_GET['max']??10000);$sql='SELECT p.*,MIN(o.price) lowest_price,COUNT(o.id) offer_count FROM products p JOIN offers o ON o.product_id=p.id AND o.stock>0 WHERE o.price BETWEEN ? AND ?';$args=[$min,$max];if($platform!==''){$sql.=' AND p.platform=?';$args[]=$platform;}if($region!==''){$sql.=' AND o.region=?';$args[]=$region;}$sql.=' GROUP BY p.id';if($q!==''){$sql.=' HAVING p.title LIKE ? OR p.search_terms LIKE ?';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}$sql.=match($sort){'price_asc'=>' ORDER BY lowest_price ASC','price_desc'=>' ORDER BY lowest_price DESC','rating'=>' ORDER BY p.rating DESC',default=>' ORDER BY p.popularity DESC'};$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();if($q!==''&&count($rows)<count($pdo->query('SELECT id FROM products')->fetchAll())){$fallback='SELECT p.*,MIN(o.price) lowest_price,COUNT(o.id) offer_count FROM products p JOIN offers o ON o.product_id=p.id AND o.stock>0 WHERE o.price BETWEEN ? AND ?';$fArgs=[$min,$max];if($platform!==''){$fallback.=' AND p.platform=?';$fArgs[]=$platform;}if($region!==''){$fallback.=' AND o.region=?';$fArgs[]=$region;}$fallback.=' GROUP BY p.id';$allStmt=$pdo->prepare($fallback);$allStmt->execute($fArgs);$all=$allStmt->fetchAll();$ids=array_column($rows,'id');foreach($all as $item){if(in_array($item['id'],$ids))continue;$score=fuzzyScore($q,$item['title'].' '.$item['search_terms']);if($score>=65){$item['match_score']=$score;$rows[]=$item;}}if(count($rows)>0&&isset($rows[0]['match_score']))usort($rows,fn($a,$b)=>($b['match_score']??100)-($a['match_score']??100));}respond(['items'=>$rows,'query'=>$q]);}
 if($method==='GET'&&preg_match('#^/products/(\d+)$#',$path,$m)){$id=(int)$m[1];$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$product=$s->fetch();if(!$product)respond(['error'=>'Product not found'],404);$s=$pdo->prepare('SELECT id,seller_name,price,region,delivery_time,rating,stock FROM offers WHERE product_id=? AND stock>0 ORDER BY price');$s->execute([$id]);respond(['product'=>$product,'offers'=>$s->fetchAll()]);}
 if($method==='GET'&&$path==='/orders'){$uid=userId();$s=$pdo->prepare('SELECT o.id,o.total,o.status,o.created_at,oi.title,oi.unit_price,oi.quantity,oi.key_value FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE o.user_id=? ORDER BY o.created_at DESC');$s->execute([$uid]);respond(['orders'=>$s->fetchAll()]);}
 if($method==='POST'&&$path==='/checkout'){$uid=userId();csrf();$b=body();$offerIds=array_values(array_unique(array_map('intval',$b['offer_ids']??[])));if(!$offerIds||count($offerIds)>20)respond(['error'=>'Your cart is empty or too large.'],422);$pdo->beginTransaction();try{$total=0.0;$selected=[];foreach($offerIds as $oid){$s=$pdo->prepare('SELECT o.id,o.product_id,o.price,o.stock,p.title FROM offers o JOIN products p ON p.id=o.product_id WHERE o.id=? FOR UPDATE');$s->execute([$oid]);$offer=$s->fetch();if(!$offer||$offer['stock']<1)throw new RuntimeException('An offer just sold out. Refresh your cart.');$k=$pdo->prepare('SELECT id,key_value FROM digital_keys WHERE offer_id=? AND is_sold=0 ORDER BY id LIMIT 1 FOR UPDATE');$k->execute([$oid]);$key=$k->fetch();if(!$key)throw new RuntimeException('Digital key stock is unavailable for '.$offer['title'].'.');$selected[]=[$offer,$key];$total+=(float)$offer['price'];}$s=$pdo->prepare("INSERT INTO orders(user_id,total,status) VALUES(?,?,'paid')");$s->execute([$uid,$total]);$orderId=(int)$pdo->lastInsertId();foreach($selected as [$offer,$key]){$s=$pdo->prepare('INSERT INTO order_items(order_id,offer_id,title,unit_price,quantity,key_value) VALUES(?,?,?,?,1,?)');$s->execute([$orderId,$offer['id'],$offer['title'],$offer['price'],$key['key_value']]);$pdo->prepare('UPDATE digital_keys SET is_sold=1,order_id=? WHERE id=?')->execute([$orderId,$key['id']]);$pdo->prepare('UPDATE offers SET stock=stock-1 WHERE id=?')->execute([$offer['id']]);}$pdo->commit();respond(['order_id'=>$orderId,'total'=>round($total,2),'status'=>'paid','message'=>'Payment simulated successfully. Your digital keys are ready in Order history.'],201);}catch(Throwable $e){$pdo->rollBack();if($e instanceof RuntimeException)respond(['error'=>$e->getMessage()],409);throw $e;}}
 respond(['error'=>'Route not found'],404);
}catch(Throwable $e){error_log((string)$e);respond(['error'=>'Something went wrong. Please try again.'],500);}
